// upsertWebhooksTx writes the typed-table portion of a webhooks upsert
// inside an existing transaction. The caller is responsible for the generic
// resources insert (via upsertGenericResourceTx) and for committing the tx.
// Splitting this out lets UpsertBatch dispatch typed inserts per item without
// opening a per-item transaction.
func (s *Store) upsertWebhooksTx(tx *sql.Tx, id string, obj map[string]any, data json.RawMessage) error {
	if _, err := tx.Exec(
		`INSERT INTO "webhooks" ("id", "data", "synced_at", "active", "callback_url", "consecutive_failures", "description", "first_consecutive_fail_date", "id_model")
		 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		 ON CONFLICT("id") DO UPDATE SET "data" = excluded."data", "synced_at" = excluded."synced_at", "active" = excluded."active", "callback_url" = excluded."callback_url", "consecutive_failures" = excluded."consecutive_failures", "description" = excluded."description", "first_consecutive_fail_date" = excluded."first_consecutive_fail_date", "id_model" = excluded."id_model"`,
		id,
		string(data),
		time.Now(),
		lookupFieldValue(obj, "active"),
		lookupFieldValue(obj, "callback_url"),
		lookupFieldValue(obj, "consecutive_failures"),
		lookupFieldValue(obj, "description"),
		lookupFieldValue(obj, "first_consecutive_fail_date"),
		lookupFieldValue(obj, "id_model"),
	); err != nil {
		return fmt.Errorf("insert into webhooks: %w", err)
	}

	return nil
}

